#!/usr/bin/env node
/*
 * emoji POS ESC/POS bridge
 * macOS local-only HTTP service. Receives a monochrome raster generated by the
 * POS browser and writes raw ESC/POS bytes to a configured CUPS print queue.
 * Chinese therefore never relies on a printer code page.
 */
'use strict';

const http = require('node:http');
const { spawn } = require('node:child_process');
const { timingSafeEqual } = require('node:crypto');
const os = require('node:os');
const fs = require('node:fs');
const path = require('node:path');

const CONFIG_PATH = process.env.ESCPOS_CONFIG || path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
const host = config.host || '127.0.0.1';
const port = Number(config.port || 17890);
const allowedOrigins = new Set(config.allowedOrigins || ['https://pos.emoji.tw', 'https://www.emoji.tw']);
const jobs = new Map();
const JOB_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_RASTER_BYTES = 4 * 1024 * 1024;

function cleanJobs() {
  const cutoff = Date.now() - JOB_TTL_MS;
  for (const [id, job] of jobs) if (job.updatedAt < cutoff) jobs.delete(id);
}
setInterval(cleanJobs, 60 * 60 * 1000).unref();

function json(res, status, body, origin) {
  if (origin && allowedOrigins.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Vary', 'Origin');
  }
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}
function equalToken(value) {
  const a = Buffer.from(String(value || ''));
  const b = Buffer.from(String(config.token || ''));
  return a.length === b.length && a.length > 0 && timingSafeEqual(a, b);
}
function authorized(req) {
  const m = String(req.headers.authorization || '').match(/^Bearer\s+(.+)$/i);
  return !!m && equalToken(m[1]);
}
function readJson(req) {
  return new Promise((resolve, reject) => {
    let size = 0, chunks = [];
    req.on('data', c => { size += c.length; if (size > MAX_RASTER_BYTES * 2) { reject(Error('請求過大')); req.destroy(); } else chunks.push(c); });
    req.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); } catch { reject(Error('JSON 格式錯誤')); } });
    req.on('error', reject);
  });
}
function rasterBytes(raster) {
  if (!raster || !Number.isInteger(raster.width) || !Number.isInteger(raster.height) || typeof raster.data !== 'string') throw Error('缺少 raster');
  const width = raster.width, height = raster.height;
  if (width < 1 || width > 1024 || height < 1 || height > 12000) throw Error('raster 尺寸不合法');
  const row = Math.ceil(width / 8), expected = row * height;
  const dots = Buffer.from(raster.data, 'base64');
  if (dots.length !== expected) throw Error('raster 資料長度不正確');
  // ESC @, line spacing 0, GS v 0 (normal raster bit image), then restore line spacing.
  const header = Buffer.from([0x1b, 0x40, 0x1b, 0x33, 0, 0x1d, 0x76, 0x30, 0, row & 0xff, row >> 8, height & 0xff, height >> 8]);
  return Buffer.concat([header, dots, Buffer.from([0x1b, 0x32])]);
}
function commandBytes(job) {
  const chunks = [];
  if (job.drawer) chunks.push(Buffer.from([0x1b, 0x70, 0, 50, 50])); // pin 2, 100 ms pulse
  if (job.raster) chunks.push(rasterBytes(job.raster));
  if (job.cut !== false && job.raster) chunks.push(Buffer.from([0x1d, 0x56, 0x42, 0])); // partial cut
  if (!chunks.length) throw Error('沒有可執行的列印內容');
  return Buffer.concat(chunks);
}
function sendMac(queue, bytes) {
  return new Promise((resolve, reject) => {
    const lp = spawn('/usr/bin/lp', ['-d', queue, '-o', 'raw'], { stdio: ['pipe', 'ignore', 'pipe'] });
    let stderr = '';
    lp.stderr.on('data', c => { stderr += c; });
    lp.on('error', reject);
    lp.on('close', code => code === 0 ? resolve() : reject(Error(stderr.trim() || `lp 結束碼 ${code}`)));
    lp.stdin.on('error', reject);
    lp.stdin.end(bytes);
  });
}
function sendWindows(queue, bytes) {
  // Windows spooler WritePrinter API, no print dialog and no code-page conversion.
  const ps = path.join(__dirname, 'raw-print.ps1');
  return new Promise((resolve, reject) => {
    const p = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', ps, '-PrinterName', queue], { stdio: ['pipe', 'ignore', 'pipe'] });
    let stderr = '';
    p.stderr.on('data', c => { stderr += c; });
    p.on('error', reject);
    p.on('close', code => code === 0 ? resolve() : reject(Error(stderr.trim() || `PowerShell 結束碼 ${code}`)));
    p.stdin.on('error', reject);
    p.stdin.end(bytes);
  });
}
function sendRaw(queue, bytes) {
  if (process.platform === 'darwin') return sendMac(queue, bytes);
  if (process.platform === 'win32') return sendWindows(queue, bytes);
  throw Error(`不支援的作業系統：${os.platform()}`);
}
async function queueJob(body) {
  const jobId = String(body.jobId || '').trim();
  const printerId = String(body.printerId || '').trim();
  if (!/^[A-Za-z0-9._:-]{1,120}$/.test(jobId)) throw Error('jobId 格式不合法');
  if (!Object.hasOwn(config.printers || {}, printerId)) throw Error('未知的 printerId');
  const existing = jobs.get(jobId);
  if (existing) return existing; // idempotent: a network retry must not print twice.
  const job = { jobId, printerId, status: 'queued', updatedAt: Date.now() };
  jobs.set(jobId, job);
  try {
    job.status = 'sending'; job.updatedAt = Date.now();
    await sendRaw(config.printers[printerId].queue, commandBytes(body));
    job.status = 'sent_to_device'; job.updatedAt = Date.now();
  } catch (error) {
    job.status = 'failed'; job.error = String(error.message || error); job.updatedAt = Date.now();
  }
  return job;
}

const server = http.createServer(async (req, res) => {
  const origin = req.headers.origin;
  if (req.method === 'OPTIONS') return json(res, allowedOrigins.has(origin) ? 204 : 403, {}, origin);
  if (origin && !allowedOrigins.has(origin)) return json(res, 403, { error: '不允許的網頁來源' }, origin);
  try {
    const url = new URL(req.url, `http://${host}:${port}`);
    if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { ok: true }, origin);
    if (!authorized(req)) return json(res, 401, { error: '未授權' }, origin);
    if (req.method === 'GET' && url.pathname === '/printers') return json(res, 200, { printers: Object.entries(config.printers || {}).map(([id, p]) => ({ id, name: p.name || id })) }, origin);
    if (req.method === 'POST' && url.pathname === '/print-jobs') {
      const job = await queueJob(await readJson(req));
      return json(res, job.status === 'failed' ? 502 : 202, { jobId: job.jobId, status: job.status, error: job.error }, origin);
    }
    const m = url.pathname.match(/^\/print-jobs\/([A-Za-z0-9._:-]+)$/);
    if (req.method === 'GET' && m) {
      const job = jobs.get(m[1]);
      return json(res, job ? 200 : 404, job ? { jobId: job.jobId, status: job.status, error: job.error } : { error: '找不到工作' }, origin);
    }
    return json(res, 404, { error: '找不到端點' }, origin);
  } catch (error) {
    return json(res, 400, { error: String(error.message || error) }, origin);
  }
});
server.listen(port, host, () => console.log(`emoji ESC/POS bridge listening on http://${host}:${port}`));
